package com.secureapp.gateway

import io.ktor.server.application.*
import io.ktor.server.engine.*
import io.ktor.server.netty.*
import io.ktor.server.response.*
import io.ktor.server.routing.*
import io.ktor.server.plugins.contentnegotiation.*
import io.ktor.serialization.kotlinx.json.*
import io.ktor.http.*
import javax.crypto.Cipher
import javax.crypto.spec.GCMParameterSpec
import javax.crypto.spec.SecretKeySpec
import java.util.Base64
import java.security.SecureRandom

data class SecurityPolicy(
    val framingPolicy: FramingDirective,
    val encryptionEnabled: Boolean,
    val storageBackend: String
)

enum class FramingDirective(val headerValue: String) {
    DENY("DENY"),
    SAMEORIGIN("SAMEORIGIN"),
    ALLOW_FROM("ALLOW-FROM")
}

class EncryptedStorageService(private val masterKey: ByteArray) {
    private val algorithm = "AES/GCM/NoPadding"
    private val tagLength = 128
    private val ivLength = 12

    init {
        // Validate the key is a proper AES key length (128/192/256-bit).
        require(masterKey.size == 16 || masterKey.size == 24 || masterKey.size == 32) {
            "Invalid AES key length: ${masterKey.size} bytes (expected 16, 24, or 32)"
        }
    }

    fun encrypt(plaintext: String): String {
        val iv = ByteArray(ivLength)
        SecureRandom().nextBytes(iv)
        val cipher = Cipher.getInstance(algorithm)
        val keySpec = SecretKeySpec(masterKey, "AES")
        val gcmSpec = GCMParameterSpec(tagLength, iv)
        cipher.init(Cipher.ENCRYPT_MODE, keySpec, gcmSpec)
        val ciphertext = cipher.doFinal(plaintext.toByteArray(Charsets.UTF_8))
        val combined = iv + ciphertext
        return Base64.getEncoder().encodeToString(combined)
    }

    fun decrypt(encoded: String): String {
        val combined = Base64.getDecoder().decode(encoded)
        // Validate the input is large enough to contain an IV plus a GCM auth tag.
        val minLength = ivLength + (tagLength / 8)
        require(combined.size >= minLength) {
            "Ciphertext too short: ${combined.size} bytes (expected at least $minLength)"
        }
        val iv = combined.sliceArray(0 until ivLength)
        val ciphertext = combined.sliceArray(ivLength until combined.size)
        val cipher = Cipher.getInstance(algorithm)
        val keySpec = SecretKeySpec(masterKey, "AES")
        val gcmSpec = GCMParameterSpec(tagLength, iv)
        cipher.init(Cipher.DECRYPT_MODE, keySpec, gcmSpec)
        return String(cipher.doFinal(ciphertext), Charsets.UTF_8)
    }
}

class SecurityHeaderMiddleware(private val policy: SecurityPolicy) {

    private val ancestorSources = mutableListOf<String>()

    fun addAllowedAncestor(origin: String) {
        ancestorSources.add(origin)
    }

    fun buildContentSecurityPolicy(): String {
        // Always enforce frame-ancestors based on policy regardless of ancestorSources
        return when (policy.framingPolicy) {
            FramingDirective.DENY -> "frame-ancestors 'none'"
            FramingDirective.SAMEORIGIN -> "frame-ancestors 'self'"
            FramingDirective.ALLOW_FROM -> {
                if (ancestorSources.isEmpty()) {
                    "frame-ancestors 'none'"
                } else {
                    "frame-ancestors ${ancestorSources.joinToString(" ")}"
                }
            }
        }
    }

    fun buildXFrameOptions(): String {
        return policy.framingPolicy.headerValue
    }

    fun applyHeaders(call: ApplicationCall) {
        val csp = buildContentSecurityPolicy()
        val xfo = buildXFrameOptions()

        // Apply X-Frame-Options for legacy browser support
        call.response.header("X-Frame-Options", xfo)

        // CSP frame-ancestors takes precedence in modern browsers
        // When both are present, CSP wins per spec
        call.response.header("Content-Security-Policy", csp)
    }
}

fun buildSecurityMiddleware(encryptedConfig: String, storageService: EncryptedStorageService): SecurityHeaderMiddleware {
    val configJson = storageService.decrypt(encryptedConfig)
    val policyType = extractPolicyFromConfig(configJson)
    val policy = SecurityPolicy(
        framingPolicy = policyType,
        encryptionEnabled = true,
        storageBackend = "aes-gcm-256"
    )
    return SecurityHeaderMiddleware(policy)
}

fun extractPolicyFromConfig(configJson: String): FramingDirective {
    // Parse the framing policy from decrypted config
    // Config format: {"framing":"DENY|SAMEORIGIN|ALLOW_FROM"}
    val framingValue = configJson
        .substringAfter("\"framing\":\"")
        .substringBefore("\"")
    return FramingDirective.valueOf(framingValue)
}

fun Application.configureRouting(middleware: SecurityHeaderMiddleware) {
    routing {
        get("/api/dashboard") {
            middleware.applyHeaders(call)
            call.respondText(
                "<html><body><h1>Secure Dashboard</h1></body></html>",
                ContentType.Text.Html
            )
        }
        get("/api/health") {
            middleware.applyHeaders(call)
            call.respondText("OK")
        }
        get("/api/settings") {
            middleware.applyHeaders(call)
            call.respondText(
                "<html><body><h1>Settings Panel</h1></body></html>",
                ContentType.Text.Html
            )
        }
    }
}

fun main() {
    val masterKey = System.getenv("MASTER_KEY")?.let {
        Base64.getDecoder().decode(it)
    } ?: ByteArray(32).also { SecureRandom().nextBytes(it) }

    val storageService = EncryptedStorageService(masterKey)

    // In production, this comes from encrypted config store
    // The encrypted config specifies DENY policy
    val encryptedConfig = storageService.encrypt("{\"framing\":\"DENY\"}")

    val middleware = buildSecurityMiddleware(encryptedConfig, storageService)

    // Register partner origins that need embedding access
    // This is loaded from an admin-configured allowlist
    val partnerOrigins = System.getenv("PARTNER_ORIGINS")?.split(",") ?: emptyList()
    partnerOrigins.forEach { middleware.addAllowedAncestor(it.trim()) }

    embeddedServer(Netty, port = 8443) {
        install(ContentNegotiation) { json() }
        configureRouting(middleware)
    }.start(wait = true)
}
